sys_fix_script.script:
(function createXurrentIMRImportTables() {

    function createTable(tableName, tableLabel, columns) {
        var check = new GlideRecord(tableName);
        if (check.isValid()) {
            gs.log('[XurrentIMR] Table already exists physically: ' + tableName);
            return;
        }

        // Remove orphaned sys_db_object record if present (metadata without physical table)
        var dbObj = new GlideRecord('sys_db_object');
        dbObj.addQuery('name', tableName);
        dbObj.query();
        while (dbObj.next()) {
            gs.log('[XurrentIMR] Removing orphaned sys_db_object for: ' + tableName);
            dbObj.deleteRecord();
        }

        try {
            var ist = new sn_impex.GlideImportSetTable(tableName);
            for (var i = 0; i < columns.length; i++) {
                var col = columns[i];
                if (col.type === 'integer') {
                    ist.addIntegerColumn(col.name);
                } else {
                    ist.addStringColumn(col.name, col.maxLength);
                }
            }
            ist.create();
            gs.log('[XurrentIMR] Created table: ' + tableName);
        } catch (e) {
            gs.logError('[XurrentIMR] Failed to create table ' + tableName + ': ' + e.message);
        }
    }

    createTable('x_xurre_imr_u_import_incident', 'Import Incident', [
        { name: 'u_operation',               type: 'string',  maxLength: 40   },
        { name: 'u_sys_id',                  type: 'string',  maxLength: 32   },
        { name: 'u_short_description',       type: 'string',  maxLength: 255  },
        { name: 'u_description',             type: 'string',  maxLength: 4000 },
        { name: 'u_urgency_sys_id',          type: 'string',  maxLength: 32   },
        { name: 'u_state_sys_id',            type: 'string',  maxLength: 32   },
        { name: 'u_snow_priority_sys_id',    type: 'string',  maxLength: 32   },
        { name: 'u_x_xurre_imr_incident',    type: 'string',  maxLength: 1024 },
        { name: 'u_entity_type_sys_id',      type: 'string',  maxLength: 32   },
        { name: 'u_entity_type_mapping_mode',type: 'integer'                  },
        { name: 'u_entity_record_sys_id',    type: 'string',  maxLength: 32   },
        { name: 'u_service_name',            type: 'string',  maxLength: 255  },
        { name: 'u_mandatory_fields',        type: 'string',  maxLength: 4000 },
        { name: 'u_result_sys_id',           type: 'string',  maxLength: 32   },
        { name: 'u_result_number',           type: 'string',  maxLength: 40   },
        { name: 'u_result_status',           type: 'string',  maxLength: 40   },
        { name: 'u_result_message',          type: 'string',  maxLength: 4000 }
    ]);

    createTable('x_xurre_imr_u_import_work_note', 'Import Work Note', [
        { name: 'u_operation',      type: 'string', maxLength: 40   },
        { name: 'u_incident_sys_id',type: 'string', maxLength: 32   },
        { name: 'u_note_sys_id',    type: 'string', maxLength: 32   },
        { name: 'u_work_note',      type: 'string', maxLength: 4000 },
        { name: 'u_result_sys_id',  type: 'string', maxLength: 32   },
        { name: 'u_result_status',  type: 'string', maxLength: 40   },
        { name: 'u_result_message', type: 'string', maxLength: 4000 }
    ]);

})();
